import { test, expect } from '@playwright/test';
test('問候語', async ({ page }) => {
  await page.setContent('<h1>hallo</h1>');
  await expect(page.getByRole('heading')).toHaveText('hello');
});

import { test, expect } from '@playwright/test';
test('送出鈕', async ({ page }) => {
  await page.setContent('<button>送出</button>');
  await expect(page.locator('div > div > button:nth-child(3)')).toBeVisible();
});
